import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:hyzen_pharmd/app/providers.dart';
import 'package:hyzen_pharmd/core/theme/app_theme.dart';
import 'package:hyzen_pharmd/core/theme/palettes.dart';
import 'package:hyzen_pharmd/core/widgets/main_dock.dart';

double contrast(Color a, Color b) {
  final x = a.computeLuminance(), y = b.computeLuminance();
  return ((x > y ? x : y) + .05) / ((x > y ? y : x) + .05);
}

void main() {
  test('default and unknown palette use teal without erasing saved choices', () async {
    SharedPreferences.setMockInitialValues({});
    final prefs = await SharedPreferences.getInstance();
    final container = ProviderContainer(overrides: [sharedPrefsProvider.overrideWithValue(prefs)]);
    addTearDown(container.dispose);
    expect(container.read(paletteColorProvider), const Color(0xFF087F76));
    container.read(paletteProvider.notifier).set('purple');
    expect(container.read(paletteColorProvider), const Color(0xFF7C3AED));
    container.read(paletteProvider.notifier).set('unknown');
    expect(container.read(paletteColorProvider), const Color(0xFF087F76));
  });

  test('brand themes meet text contrast and retain Manrope', () {
    expect(AppTheme.light().scaffoldBackgroundColor, const Color(0xFFF3F8F7));
    expect(AppTheme.light().colorScheme.surface, Colors.white);
    for (final theme in [AppTheme.light(), AppTheme.dark()]) {
      final c = theme.colorScheme;
      for (final pair in [(c.onPrimary, c.primary), (c.onSurface, c.surface),
        (c.onSurfaceVariant, c.surface), (c.onPrimaryContainer, c.primaryContainer)]) {
        expect(contrast(pair.$1, pair.$2), greaterThanOrEqualTo(4.5));
      }
      expect(theme.textTheme.bodyMedium?.fontFamily, 'Manrope');
    }
  });

  for (final dark in [false, true]) {
    for (final scale in [1.0, 2.0, 3.0]) {
      testWidgets('dock reflows at 320dp, scale $scale, dark $dark', (tester) async {
        tester.view.physicalSize = const Size(320, 900);
        tester.view.devicePixelRatio = 1;
        addTearDown(tester.view.resetPhysicalSize);
        addTearDown(tester.view.resetDevicePixelRatio);
        await tester.pumpWidget(MaterialApp(
          theme: dark ? AppTheme.dark() : AppTheme.light(),
          home: MediaQuery(
            data: MediaQueryData(size: const Size(320, 900),
              textScaler: TextScaler.linear(scale), disableAnimations: true),
            child: const Scaffold(bottomNavigationBar: MainDock(path: '/study')),
          ),
        ));
        await tester.pumpAndSettle();
        expect(tester.takeException(), isNull);
        expect(find.byType(InkWell), findsNWidgets(4));
        for (final route in ['/home', '/study', '/pdf-studio', '/shop']) {
          final size = tester.getSize(find.byKey(ValueKey('dock-$route')));
          expect(size.width, greaterThanOrEqualTo(48));
          expect(size.height, greaterThanOrEqualTo(48));
        }
        for (final widget in tester.widgetList<AnimatedContainer>(find.byType(AnimatedContainer))) {
          expect(widget.duration, Duration.zero);
        }
      });
    }
  }
}

