import 'package:flutter/material.dart';

/// Hyzen V3 design tokens. All screens must use these instead of literals.
/// Slate / Deep Teal academic design; secondary accents identify library categories.
class HColors {
  HColors._();
  // Brand
  static const primary = Color(0xFF087F76);
  static const primaryDeep = Color(0xFF075E58);
  static const primarySoft = Color(0xFFDDEDEA);
  static const teal = Color(0xFF087F76);
  static const onPrimary = Colors.white;

  // Ink (deep navy)
  static const ink = Color(0xFF1A3440);
  static const ink2 = Color(0xFF507379);
  static const ink3 = Color(0xFF507379);

  // Surfaces (light)
  static const background = Color(0xFFF3F8F7);
  static const surface = Colors.white;
  static const surfaceAlt = Color(0xFFDDEDEA);
  static const outline = Color(0x0A4F327D);
  static const outlineStrong = Color(0x2E0E1B2C);

  // Status
  static const success = Color(0xFF13854F);
  static const warning = Color(0xFFB7791F);
  static const error = Color(0xFFC0392B);
  static const info = Color(0xFF246FA8);

  // Dark
  static const darkBackground = Color(0xFF101F25);
  static const darkSurface = Color(0xFF1C343D);
  static const darkSurfaceAlt = Color(0xFF29434B);
  static const darkInk = Color(0xFFF3F8F7);
  static const darkInk2 = Color(0xFFB6CECC);

